    Exercise(
        id="ex_sql_ds6_ytd",
        title="Validate a Power BI YTD measure",
        module="descriptive", language="sql", difficulty="Advanced", topic="Running totals by partition",
        competencies=["bi_modeling", "sql_window"], lesson="ds6",
        business_question="Your Power BI report shows `Revenue YTD`. Reproduce it in SQL so the measure can be validated before publishing.",
        dataset="retail", tables=["retail.orders", "retail.order_items"], search_path="retail",
        requirements=[
            "Columns: `year`, `month` (1-12), `revenue`, `revenue_ytd`; both money columns rounded to 2.",
            "Completed orders, 2023 and 2024. revenue_ytd restarts every January.",
            "Order by year, month.",
        ],
        expected_output="24 rows.",
        starter_code="WITH monthly AS (\n    SELECT YEAR(o.order_date) AS year, MONTH(o.order_date) AS month,\n           SUM(oi.quantity * oi.unit_price * (1 - COALESCE(oi.discount_pct, 0))) AS revenue\n    FROM orders o JOIN order_items oi ON oi.order_id = o.order_id\n    WHERE o.status = 'Completed'\n    GROUP BY 1, 2\n)\nSELECT * FROM monthly ORDER BY year, month;\n",
        solution="WITH monthly AS (\n    SELECT YEAR(o.order_date) AS year, MONTH(o.order_date) AS month,\n           SUM(oi.quantity * oi.unit_price * (1 - COALESCE(oi.discount_pct, 0))) AS revenue\n    FROM orders o JOIN order_items oi ON oi.order_id = o.order_id\n    WHERE o.status = 'Completed'\n    GROUP BY 1, 2\n)\nSELECT year, month, ROUND(revenue, 2) AS revenue,\n       ROUND(SUM(revenue) OVER (PARTITION BY year ORDER BY month), 2) AS revenue_ytd\nFROM monthly\nORDER BY year, month;",
        explanation="TOTALYTD in DAX = a running sum partitioned by year and ordered by month.",
        hints=["SUM(revenue) OVER (...) creates a running total.", "PARTITION BY year makes it restart every January."],
        order_matters=True, rubric=SQL_RUBRIC,
    ),
    Exercise(
        id="ex_sql_ds7_monthly_kpis",
        title="Monthly KPI report (2024)",
        module="descriptive", language="sql", difficulty="Professional", topic="KPI reporting",
        competencies=["kpi_reporting", "sql_joins", "sql_aggregation"], lesson="ds7",
        business_question="Build the CEO's 2024 monthly KPI table.",
        dataset="retail", tables=["retail.orders", "retail.order_items", "retail.products"], search_path="retail",
        requirements=[
            "Columns: `month` (DATE, first of month), `orders` (distinct completed orders), `revenue` (2 dp), `aov` (revenue / orders, 2 dp), `gross_margin_pct` (100*(revenue-cost)/revenue, 1 dp).",
            "cost = SUM(quantity * products.unit_cost). Completed orders in 2024. Order by month.",
            "Compute ratios from unrounded sums.",
        ],
        expected_output="12 rows ordered by month.",
        starter_code="WITH lines AS (\n    SELECT o.order_id,\n           CAST(DATE_TRUNC('month', o.order_date) AS DATE) AS month\n           -- add revenue and cost per line\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.order_id\n    JOIN products p ON p.product_id = oi.product_id\n    WHERE o.status = 'Completed' AND YEAR(o.order_date) = 2024\n)\nSELECT month FROM lines GROUP BY month ORDER BY month;\n",
        solution="WITH lines AS (\n    SELECT o.order_id,\n           CAST(DATE_TRUNC('month', o.order_date) AS DATE) AS month,\n           oi.quantity * oi.unit_price * (1 - COALESCE(oi.discount_pct, 0)) AS revenue,\n           oi.quantity * p.unit_cost AS cost\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.order_id\n    JOIN products p ON p.product_id = oi.product_id\n    WHERE o.status = 'Completed' AND YEAR(o.order_date) = 2024\n)\nSELECT month,\n       COUNT(DISTINCT order_id) AS orders,\n       ROUND(SUM(revenue), 2) AS revenue,\n       ROUND(SUM(revenue) / COUNT(DISTINCT order_id), 2) AS aov,\n       ROUND(100 * (SUM(revenue) - SUM(cost)) / SUM(revenue), 1) AS gross_margin_pct\nFROM lines\nGROUP BY month\nORDER BY month;",
        explanation="Because the CTE is at line grain, orders must be counted with COUNT(DISTINCT order_id). AOV and margin are ratios of sums.",
        hints=["At line grain, COUNT(*) counts lines, not orders.", "AOV = SUM(revenue) / COUNT(DISTINCT order_id).", "CAST(DATE_TRUNC('month', ...) AS DATE) gives a DATE month."],
        order_matters=True, rubric=SQL_RUBRIC,
    ),
    Exercise(
        id="ex_sql_ds7_return_rates",
        title="Return rates and refund cost by category",
        module="descriptive", language="sql", difficulty="Professional", topic="Aggregating before joining",
        competencies=["kpi_reporting", "sql_joins"], lesson="ds7", kind="challenge",
        business_question="Which categories have the highest return rates, and what do refunds cost?",
        dataset="retail", tables=["retail.order_items", "retail.orders", "retail.returns", "retail.products", "retail.categories"], search_path="retail",
        requirements=[
            "Consider order lines of Completed orders.",
            "Columns: `category_name`, `lines` (count of such lines), `returned_lines` (lines with at least one return), `return_rate_pct` (100*returned/lines, 2 dp), `refunds` (sum of refund_amount, 2 dp).",
            "Order by return_rate_pct descending.",
        ],
        expected_output="8 rows.",
        starter_code="-- Tip: aggregate returns to one row per order_item_id before joining\n",
        solution="WITH ret AS (\n    SELECT order_item_id, SUM(refund_amount) AS refund\n    FROM returns GROUP BY order_item_id\n)\nSELECT c.category_name,\n       COUNT(*) AS lines,\n       COUNT(ret.order_item_id) AS returned_lines,\n       ROUND(100.0 * COUNT(ret.order_item_id) / COUNT(*), 2) AS return_rate_pct,\n       ROUND(COALESCE(SUM(ret.refund), 0), 2) AS refunds\nFROM order_items oi\nJOIN orders o ON o.order_id = oi.order_id\nJOIN products p ON p.product_id = oi.product_id\nJOIN categories c ON c.category_id = p.category_id\nLEFT JOIN ret ON ret.order_item_id = oi.order_item_id\nWHERE o.status = 'Completed'\nGROUP BY c.category_name\nORDER BY return_rate_pct DESC;",
        explanation="A LEFT JOIN keeps lines without returns; COUNT(ret.order_item_id) counts only matched (returned) lines. Aggregating returns first prevents double counting if a line had multiple returns.",
        hints=["LEFT JOIN returns so non-returned lines stay in the denominator.", "COUNT(column) ignores NULLs - useful for counting matches.", "Pre-aggregate returns per order_item_id in a CTE."],
        rubric=SQL_RUBRIC,
    ),
